// Shared data model. Game data is generated by tools/import-*.ts into
// public/data/<game>.json; factories and worlds are hand-edited through the UI
// and saved as JSON under factories/<game>/.
//
// Units: every rate the engine reports is per minute. Recipe stack amounts are
// per cycle; fluids are in m³ (Satisfactory) or fluid units (Factorio).

export type GameId = 'satisfactory' | 'factorio' | 'dsp';

/** Pseudo-item for electricity. Generators produce it; machines consume it. */
export const POWER = '@power';

export interface Item {
  id: string;
  name: string;
  form?: 'solid' | 'liquid' | 'gas';
  /** Mined or pumped, never crafted from other items in normal play. */
  raw?: boolean;
  /** Default recipe for this item in target mode. */
  recipe?: string;
  /** Fuel value in MJ per item (per m³ for fluids). */
  energyMJ?: number;
}

export interface Building {
  id: string;
  name: string;
  /** Draw in MW at 100% clock / speed 1, before sloops or modules. */
  powerMW: number;
  /** Satisfactory: power scales by clock^exponent. Absent = linear. */
  powerExponent?: number;
  /** Crafting speed multiplier (Factorio, DSP). Default 1. */
  speed?: number;
  /** Built-in productivity bonus, e.g. 0.5 for +50% (Factorio foundry). */
  baseProductivity?: number;
  /** Satisfactory production-amplifier (somersloop) slots. */
  sloopSlots?: number;
  /** Floor area per machine: m² (Satisfactory) or tiles (Factorio). */
  footprint?: number;
  /** Factorio crafting categories this machine accepts. */
  categories?: string[];
  moduleSlots?: number;
}

export interface Stack {
  item: string;
  amount: number;
}

export interface Recipe {
  id: string;
  name: string;
  /** Seconds per cycle at speed 1 / 100% clock. */
  time: number;
  inputs: Stack[];
  outputs: Stack[];
  /** Building ids able to run this recipe; the first is the default. */
  buildings: string[];
  category?: string;
  /** Satisfactory alternate recipe (must be unlocked by hard drive). */
  alternate?: boolean;
  /** Variable-power recipes (Satisfactory particle accelerator etc.), MW at 100%. */
  power?: { min: number; max: number };
  /** Generator recipe: MW produced per machine at 100% clock. */
  generatesMW?: number;
  /** Factorio: productivity bonuses may apply. */
  allowProductivity?: boolean;
  /** Factorio: per-output amount that productivity does not multiply. */
  ignoredByProductivity?: Record<string, number>;
}

export interface GameFeatures {
  clock: boolean;
  sloops: boolean;
  power: boolean;
  productivity: boolean;
  speedBonus: boolean;
  footprint: boolean;
  /** Footprint unit label. */
  areaUnit?: 'm²' | 'tiles';
}

export interface GameData {
  game: GameId;
  name: string;
  /** Where the data came from, e.g. the docs file path and game version. */
  source: string;
  generatedAt: string;
  items: Record<string, Item>;
  buildings: Record<string, Building>;
  recipes: Record<string, Recipe>;
  features: GameFeatures;
  /** Items imported by default (raw resources, water). */
  defaultImports: string[];
  /** Relative scarcity weights for raw items, used by the min-raw objective. */
  resourceWeights?: Record<string, number>;
  /** Importer notes: skipped records and why. */
  skipped?: { id: string; reason: string }[];
}

// ---------------------------------------------------------------------------
// Factory documents

export interface LineSettings {
  /** Satisfactory clock, 0.01–2.5 (1 = 100%). */
  clock?: number;
  /** Somersloops slotted. */
  sloops?: number;
  /** Override the recipe's default building. */
  building?: string;
  /** Extra speed, 0.5 = +50% (Factorio modules/beacons, DSP proliferator). */
  speedBonus?: number;
  /** Extra productivity, 0.25 = +25%. */
  prodBonus?: number;
}

export interface Line extends LineSettings {
  id: string;
  recipe: string;
  /** Locked machine count; null or absent lets the solver size the line. */
  machines?: number | null;
  note?: string;
}

export type Objective = 'min-raw' | 'min-power' | 'min-machines';

export interface Target {
  item: string;
  rate: number;
}

export interface FactoryImports {
  /** Items imported everywhere they are consumed. */
  items: string[];
  /** Per-consumer imports, `${item}>${lineId}`. */
  edges: string[];
  /** Default imports (raw items) the user wants produced instead. */
  exclude: string[];
}

export interface Factory {
  schema: 1;
  id: string;
  game: GameId;
  name: string;
  notes?: string;
  /** target: the solver picks lines to meet targets. manual: you type the lines. */
  mode: 'target' | 'manual';
  objective: Objective;
  targets: Target[];
  /** Target mode: item -> recipe id chosen to make it. */
  recipeChoice: Record<string, string>;
  /** Target mode: let the solver choose among all unlocked recipes. */
  optimize?: boolean;
  /** Target mode: settings for the auto line of each recipe. */
  lineSettings: Record<string, LineSettings>;
  /** Manual lines, plus locked extra lines in target mode. */
  lines: Line[];
  imports: FactoryImports;
  /** Floor spacing factor for foundation counts (Satisfactory). */
  spacing: number;
  createdAt: string;
  updatedAt: string;
}

export interface WorldEntry {
  factory: string;
  multiplier: number;
}

export interface World {
  schema: 1;
  id: string;
  game: GameId;
  name: string;
  entries: WorldEntry[];
  createdAt: string;
  updatedAt: string;
}

export interface GameSettings {
  /** Unlocked alternate recipe ids (Satisfactory). */
  unlocked: string[];
  /** Factorio: preferred building per crafting category. */
  defaultBuilding: Record<string, string>;
  /** Default spacing factor for new factories. */
  spacing: number;
}

// ---------------------------------------------------------------------------
// Solver output

export interface PlanLine {
  id: string;
  recipe: string;
  building: string;
  machines: number;
  locked: boolean;
  /** Generated from targets rather than typed by the user. */
  auto: boolean;
  settings: LineSettings;
  /** Net per-minute flow of the whole line, by item (+ produced, − consumed). */
  rates: Record<string, number>;
  /** MW drawn by the whole line (negative = generated). */
  powerMW: number;
  /** Floor area of the whole line, whole machines. */
  footprint: number;
}

export interface PlanItem {
  item: string;
  produced: number;
  consumed: number;
  imported: number;
  surplus: number;
  target: number;
  /** Demand the plan could not meet: no recipe and not importable. */
  unbalanced: number;
}

/** Flow of one item from a source (line id or 'import') to a consumer line. */
export interface PlanEdge {
  item: string;
  from: string;
  to: string;
  rate: number;
}

export interface Plan {
  status: 'ok' | 'unbalanced' | 'error';
  message?: string;
  lines: PlanLine[];
  items: Record<string, PlanItem>;
  edges: PlanEdge[];
  /** Net MW drawn (consumption − generation). */
  powerMW: number;
  generatedMW: number;
  consumedMW: number;
  machines: number;
  footprint: number;
  /** footprint × spacing / 64, Satisfactory only. */
  foundations?: number;
  warnings: string[];
}
